function getEffectiveTargetSize(el) {
  const r = el.getBoundingClientRect();
  let w = r.width;
  let h = r.height;
  const after = window.getComputedStyle(el, '::after');
  if (after && after.content && after.content !== 'none') {
    const top = Math.abs(parseFloat(after.top) || 0);
    const bottom = Math.abs(parseFloat(after.bottom) || 0);
    const left = Math.abs(parseFloat(after.left) || 0);
    const right = Math.abs(parseFloat(after.right) || 0);
    w = Math.max(w, r.width + left + right);
    h = Math.max(h, r.height + top + bottom);
  }
  return { width: w, height: h };
}

